import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def is_prime_power(n):
    if n <= 1:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n //= i
            return n == 1
        i += 1
    return True

count_failing = 0
for m in range(2, 2001):
    if not is_prime(m) and is_prime_power(m):
        # Composite prime power: e.g., 4, 8, 9, 25
        count_failing += 1
    elif is_prime(m):
        # Prime numbers: e.g., 2, 3, 5
        count_failing += 1

